import { html, nothing } from 'lit'
import { DsElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// AnnouncementBar.vue as <conare-announcement-bar>: one line above the website's header: the whole ribbon is the link.
// The red wash, the only ground approved under off-black text; a square black tag in the site tag's capitals that turns
// red as the ribbon is hovered; the line, and the call to action running on in the same sentence, underlined close
// (from sm). The ribbon deepens to the hover wash in 200ms. It sits at z-10 so a pinned footer never reaches over it.

/** @summary One line above the website's header; the whole ribbon is the link. */
export class AnnouncementBar extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { tag: {}, text: {}, cta: {}, href: {} }

	/** The square black tag (New). */
	tag = ''
	/** The line. */
	text = ''
	/** The call to action, running on in the same sentence. */
	cta?: string
	href = ''

	render() {
		return html`<a data-ds="announcement-bar" href=${this.href} class="group relative z-10 block bg-red-wash text-off-black transition-colors duration-200 ease-standard hover:bg-home-wash-hover">
			<span class="mx-auto flex h-9 max-w-[1440px] items-center justify-center gap-2 px-4 text-ui sm:px-6 lg:px-10">
				<span class="shrink-0 bg-off-black py-0.75 pr-[calc(4px-0.06em)] pl-1 type-tag text-off-white transition-colors duration-200 ease-standard [text-box:trim-both_cap_alphabetic] group-hover:bg-home-red">${this.tag}</span>
				<span class="truncate leading-4">${this.text}${this.cta ? html` <span class="hidden underline decoration-off-black/30 underline-offset-2 transition-colors duration-200 ease-standard group-hover:decoration-off-black sm:inline">${this.cta}</span>` : nothing}</span>
			</span>
		</a>`
	}
}

define('announcement-bar', AnnouncementBar)
